namespace Nexora.Domain.Couples;

public enum InvitationStatus
{
    Pending = 0,
    Accepted = 1,
    Rejected = 2,
    Expired = 3,
    Revoked = 4
}

/// <summary>
/// A single-use, time-limited invitation token generated by User A for User B to join a couple.
/// </summary>
public sealed class CoupleInvitation
{
    public Guid Id { get; set; } = Guid.NewGuid();

    /// <summary>User who initiated and generated the invitation code.</summary>
    public Guid SenderId { get; set; }

    /// <summary>Cryptographically random invitation code (e.g. 6-8 chars alphanumeric).</summary>
    public string InvitationCode { get; set; } = string.Empty;

    public InvitationStatus Status { get; set; } = InvitationStatus.Pending;

    public DateTime ExpiresAtUtc { get; set; }
    public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow;
    public DateTime? AcceptedAtUtc { get; set; }
    public Guid? AcceptedByUserId { get; set; }

    public bool IsValid() => Status == InvitationStatus.Pending && DateTime.UtcNow < ExpiresAtUtc;
}
